using Sigov.Application.Agro.Permissions; using Sigov.Application.Common; using Sigov.Domain.Common;
namespace Sigov.Application.Agro.FeirasMercados;
public sealed class AgroFeiraValidator{public Result Validar(AgroFeiraCreateRequest r)=>string.IsNullOrWhiteSpace(r.Codigo)?Result.Failure("Feira exige código."):string.IsNullOrWhiteSpace(r.Nome)?Result.Failure("Feira exige nome."):string.IsNullOrWhiteSpace(r.Local)?Result.Failure("Feira exige local."):Result.Success();}
public sealed class AgroFeiranteValidator{public Result Validar(AgroFeiranteCreateRequest r)=>!r.ProdutorId.HasValue&&!r.PessoaId.HasValue?Result.Failure("Feirante exige produtor ou pessoa."):string.IsNullOrWhiteSpace(r.NumeroCadastro)?Result.Failure("Número de cadastro é obrigatório."):Result.Success();}
public sealed class AgroFeiraService:IAgroFeiraService{private readonly IAgroAccessChecker _a;private readonly AgroFeiraValidator _v;private readonly IAgroFeirasRepository _r; public AgroFeiraService(IAgroAccessChecker a,AgroFeiraValidator v,IAgroFeirasRepository r){_a=a;_v=v;_r=r;} async Task<Result<AgroAccessContext>> C(string p,CancellationToken ct)=>await _a.CheckAsync(new AgroAccessRequest(p,"agro.feiras"),ct); public async Task<Result<PagedResult<AgroFeiraResponse>>> ListarAsync(int page,int pageSize,CancellationToken ct){var c=await C(AgroPermissions.FeiraVisualizar,ct); if(c.IsFailure)return Result<PagedResult<AgroFeiraResponse>>.Failure(c.Error!); return Result<PagedResult<AgroFeiraResponse>>.Success(await _r.ListarFeirasAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,Math.Max(1,page),Math.Clamp(pageSize,1,100),ct));} public async Task<Result<AgroFeiraResponse>> ObterAsync(long id,CancellationToken ct){var c=await C(AgroPermissions.FeiraVisualizar,ct); if(c.IsFailure)return Result<AgroFeiraResponse>.Failure(c.Error!); var row=await _r.ObterFeiraAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,id,ct); return row is null?Result<AgroFeiraResponse>.Failure("Feira não encontrada."):Result<AgroFeiraResponse>.Success(row);} public async Task<Result<long>> CriarAsync(AgroFeiraCreateRequest r,CancellationToken ct){var c=await C(AgroPermissions.FeiraCriar,ct); if(c.IsFailure)return Result<long>.Failure(c.Error!); var v=_v.Validar(r); if(v.IsFailure)return Result<long>.Failure(v.Error!); return Result<long>.Success(await _r.CriarFeiraAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,c.Value.UsuarioId,r,ct));} public async Task<Result> AtualizarAsync(long id,AgroFeiraCreateRequest r,CancellationToken ct){var c=await C(AgroPermissions.FeiraEditar,ct); if(c.IsFailure)return Result.Failure(c.Error!); var v=_v.Validar(r); if(v.IsFailure)return v; await _r.AtualizarFeiraAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,id,c.Value.UsuarioId,r,ct); return Result.Success();} public async Task<Result> ExcluirAsync(long id,CancellationToken ct){var c=await C(AgroPermissions.FeiraExcluir,ct); if(c.IsFailure)return Result.Failure(c.Error!); await _r.ExcluirFeiraAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,id,c.Value.UsuarioId,ct); return Result.Success();}}
public sealed class AgroFeiranteService:IAgroFeiranteService{private readonly IAgroAccessChecker _a;private readonly AgroFeiranteValidator _v;private readonly IAgroFeirasRepository _r; public AgroFeiranteService(IAgroAccessChecker a,AgroFeiranteValidator v,IAgroFeirasRepository r){_a=a;_v=v;_r=r;} async Task<Result<AgroAccessContext>> C(string p,CancellationToken ct)=>await _a.CheckAsync(new AgroAccessRequest(p,"agro.feiras"),ct); public async Task<Result<PagedResult<AgroFeiranteResponse>>> ListarAsync(int page,int pageSize,CancellationToken ct){var c=await C(AgroPermissions.FeiranteVisualizar,ct); if(c.IsFailure)return Result<PagedResult<AgroFeiranteResponse>>.Failure(c.Error!); return Result<PagedResult<AgroFeiranteResponse>>.Success(await _r.ListarFeirantesAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,page,pageSize,ct));} public async Task<Result<long>> CriarAsync(long feiraId,AgroFeiranteCreateRequest r,CancellationToken ct){var c=await C(AgroPermissions.FeiranteCriar,ct); if(c.IsFailure)return Result<long>.Failure(c.Error!); var req=r with{FeiraId=feiraId}; var v=_v.Validar(req); if(v.IsFailure)return Result<long>.Failure(v.Error!); return Result<long>.Success(await _r.CriarFeiranteAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,feiraId,c.Value.UsuarioId,req,ct));} public async Task<Result> AtualizarAsync(long id,AgroFeiranteCreateRequest r,CancellationToken ct){var c=await C(AgroPermissions.FeiranteEditar,ct); if(c.IsFailure)return Result.Failure(c.Error!); await _r.AtualizarFeiranteStatusAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,id,r.Situacao,r.Autorizado,c.Value.UsuarioId,ct); return Result.Success();} public Task<Result> AutorizarAsync(long id,CancellationToken ct)=>Status(id,"AUTORIZADO",true,AgroPermissions.FeiranteAutorizar,ct); public Task<Result> SuspenderAsync(long id,CancellationToken ct)=>Status(id,"SUSPENSO",false,AgroPermissions.FeiranteSuspender,ct); async Task<Result> Status(long id,string s,bool aut,string p,CancellationToken ct){var c=await C(p,ct); if(c.IsFailure)return Result.Failure(c.Error!); await _r.AtualizarFeiranteStatusAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,id,s,aut,c.Value.UsuarioId,ct); return Result.Success();} public async Task<Result<PagedResult<AgroBancaFeiraResponse>>> ListarBancasAsync(long feiraId,CancellationToken ct){var c=await C(AgroPermissions.FeiraVisualizar,ct); if(c.IsFailure)return Result<PagedResult<AgroBancaFeiraResponse>>.Failure(c.Error!); return Result<PagedResult<AgroBancaFeiraResponse>>.Success(await _r.ListarBancasAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,feiraId,ct));} public async Task<Result<long>> CriarBancaAsync(long feiraId,AgroBancaFeiraCreateRequest r,CancellationToken ct){var c=await C(AgroPermissions.FeiranteCriar,ct); if(c.IsFailure)return Result<long>.Failure(c.Error!); return Result<long>.Success(await _r.CriarBancaAsync(c.Value!.TenantId,c.Value.EntidadeId!.Value,feiraId,c.Value.UsuarioId,r with{FeiraId=feiraId},ct));}}
